  "implementation": "def solve(case):
    segments = case['segments']
    budget = case['budget']
    total_min = sum(s['minimum'] for s in segments)
    total_cap = sum(s['capacity'] for s in segments)
    if budget < total_min or budget > total_cap:
        return {'error': 'Budget out of range'}
    allocations = {s['name']: s['minimum'] for s in segments}
    remaining = budget - total_min
    while remaining > 0:
        best_seg = None
        best_ratio = -1.0
        for seg in segments:
            name = seg['name']
            if allocations[name] < seg['capacity']:
                ratio = seg['importance'] / (allocations[name] + 1)
                if ratio > best_ratio:
                    best_ratio = ratio
                    best_seg = seg
        if best_seg is None:
            break
        allocations[best_seg['name']] += 1
        remaining -= 1
    return {'allocations': allocations, 'names': [s['name'] for s in segments], 'total': budget}
